function craftPlanAuditLabels(sources = {}, materials = []) {
  const storage = Object.fromEntries((sources.storage ?? []).map((source) => [String(source.sourceId), String(source.label ?? source.sourceId)]));
  const players = Object.fromEntries((sources.players ?? []).map((source) => [String(source.playerId), String(source.label ?? source.playerId)]));
  const playerBank = Object.fromEntries((sources.banks ?? []).map((source) => [String(source.sourceId), String(source.label ?? source.sourceId)]));
  const deployable = Object.fromEntries((sources.deployables ?? []).map((source) => [String(source.sourceId), String(source.label ?? source.sourceId)]));
  const gatheredItem = Object.fromEntries((materials ?? []).map((item) => {
    const key = String(item.key ?? `${item.kind === "cargo" || item.itemType === 1 ? "cargo" : "items"}:${item.id}`);
    return [key, String(item.name ?? key)];
  }));
  return { storage, player_inventory: players, player_crafts: players, player_bank: playerBank, deployable, gathered_item: gatheredItem };
}


async function computedCraftPlanResponse(claimId = getSettings().claimId, options = {}) {
  return (await computedCraftPlanWorkspace(claimId, options)).plan;
}

async function craftPlanSourceResult(source, load) {
  try {
    return { source, value: await load(), error: "" };
  } catch (error) {
    return {
      source,
      value: null,
      error: error instanceof Error ? error.message : String(error),
    };
  }
}

async function computedCompactCraftPlanResponse(claimId = getSettings().claimId, options = {}) {
  return (await computedCraftPlanWorkspace(claimId, options)).compact();
}

function craftPlanCurrentSourceRevision(claimId) {
  return ["members", "inventories", "crafts", "construction", "catalogs"]
    .map((domain) => `${domain}:${currentStateRepository.read(String(claimId), domain)?.generation ?? 0}`)
    .join("|");
}

function craftPlanBaselineChangeSince(claimId, since = "") {
  try {
    const change = craftPlanProgressAudit.latestBaselineChange(claimId);
    if (!change) return null;
    const changedAt = new Date(change.changedAt ?? change.capturedAt).getTime();
    const threshold = since ? new Date(since).getTime() : Number.NEGATIVE_INFINITY;
    return Number.isFinite(changedAt) && (!Number.isFinite(threshold) || changedAt > threshold) ? change : null;
  } catch (error) {
    console.warn(`Craft Plan baseline audit read failed: ${error instanceof Error ? error.message : String(error)}`);
    return null;
  }
}

function craftPlanWithBaselineChange(plan, baselineChange) {
  const { baselineChange: ignored, ...effortProgress } = plan?.effortProgress ?? {};
  return {
    ...plan,
    effortProgress: baselineChange ? { ...effortProgress, baselineChange } : effortProgress,
  };
}

async function computedCraftPlanWorkspace(claimId = getSettings().claimId, options = {}) {
  const normalizedClaimId = String(claimId ?? "").trim();
  const now = Date.now();
  const cached = craftPlanResponseCache.get(normalizedClaimId);
  const forceRefresh = options.forceRefresh === true;
  const refreshId = String(options.refreshId ?? "");
  let sourceRevision = craftPlanCurrentSourceRevision(normalizedClaimId);
  if (cached && cached.expiresAt > now && cached.sourceRevision === sourceRevision && (!forceRefresh || cached.refreshId === refreshId)) { plannerTelemetry.cacheHits += 1; return cached.workspace; }
  const existing = craftPlanResponseInflight.get(normalizedClaimId);
  if (existing?.generation === craftPlanResponseGeneration && existing?.sourceRevision === sourceRevision && (!forceRefresh || existing.refreshId === refreshId)) { plannerTelemetry.inflightReuse += 1; return existing.promise; }
  if (forceRefresh && relayProviderStarted) {
    try {
      await relayProvider.refresh({
        claimId: normalizedClaimId,
        domains: ["inventories", "crafts"],
        reason: "manual",
      });
    } catch {
      // The calculation below deliberately uses the durable last-good generation.
    }
    sourceRevision = craftPlanCurrentSourceRevision(normalizedClaimId);
  }
  const generation = craftPlanResponseGeneration;
  const startedAt = Date.now();
  plannerTelemetry.freshCalculations += 1;
  const promise = computedCraftPlanResponseFresh(normalizedClaimId, { forceRefresh }).then((plan) => {
    const workspace = createCraftPlanResponseWorkspace(plan);
    plannerTelemetry.lastDurationMs = Date.now() - startedAt;
    plannerTelemetry.lastCompletedAt = new Date().toISOString();
    if (
      generation === craftPlanResponseGeneration
      && craftPlanCurrentSourceRevision(normalizedClaimId) === sourceRevision
    ) {
      craftPlanResponseCache.set(normalizedClaimId, {
        workspace,
        sourceRevision,
        expiresAt: Date.now() + CRAFT_PLAN_RESPONSE_CACHE_TTL_MS,
        refreshId: forceRefresh ? refreshId : "",
      });
    }
    return workspace;
  }).finally(() => {
    if (craftPlanResponseInflight.get(normalizedClaimId)?.promise === promise) craftPlanResponseInflight.delete(normalizedClaimId);
  });
  craftPlanResponseInflight.set(normalizedClaimId, {
    generation,
    sourceRevision,
    promise,
    refreshId: forceRefresh ? refreshId : "",
  });
  return promise;
}

async function computedCraftPlanResponseFresh(claimId = getSettings().claimId, options = {}) {
  const forceRefresh = options.forceRefresh === true;
  let config = storedCraftPlanConfig();
  if (!config.enabled || !config.targets.length) {
    const plan = computeCraftPlan({ config });
    plan.effortProgress = calculateCraftPlanEffortProgress({ baselinePlan: plan, currentPlan: plan, weights: new Map() });
    return plan;
  }
  try {
    const buildingsPayload = currentClaimBuildingsProjection(claimId);
    const reconciled = reconcileCraftPlanBuildingProgress(config, buildingsPayload);
    config = reconciled.changed ? saveCraftPlanConfig(reconciled.config) : reconciled.config;
  } catch {
    // Keep prior baselines and observed completions while the first Relay building generation loads.
  }
  const catalogTargets = craftPlanCatalogTargets(config);
  const { detailsByKey, warnings: catalogWarnings } = collectLocalCatalogCraftPlanDetails(
    gameCatalogRepository,
    catalogTargets,
    config.routeOverrides,
    64,
    [],
    { requireValidatedProbabilities: true },
  );
  const [inventoriesResult, craftsResult, membersPayload] = await Promise.all([
    craftPlanSourceResult(
      { sourceId: String(claimId), label: "Settlement inventories", type: "Settlement storage" },
      () => currentInventoryProjection(claimId),
    ),
    craftPlanSourceResult(
      { sourceId: String(claimId), label: "Settlement crafts", type: "Tracked crafts" },
      () => currentCraftPlanProjection(claimId),
    ),
    Promise.resolve().then(() => currentMembersProjection(claimId)).catch(() => ({ members: [] })),
  ]);
  const inventoriesPayload = inventoriesResult.value ?? { buildings: [] };
  const craftsPayload = craftsResult.value ?? { craftResults: [] };
  if (Array.isArray(craftsPayload.warnings)) {
    catalogWarnings.push(...craftsPayload.warnings);
  }
  const sourceFailures = [inventoriesResult, craftsResult]
    .filter((result) => result.error)
    .map((result) => ({ ...result.source, error: result.error }));
  const memberNames = new Map(unwrap(membersPayload, "members", []).map((member) => {
    const playerId = String(member.playerEntityId ?? member.entityId ?? "");
    return [playerId, String(member.userName ?? member.username ?? playerId)];
  }));
  const storageSources = settlementStorageSourcesFromInventories(inventoriesPayload, config.sourceRules.storageContainerIds);
  const playerSources = [];
  const bankSources = [];
  const deployableSources = [];
  const inventoryPlayerIds = new Set(config.sourceRules.playerIds.map(String));
  const bankPlayerIds = new Set(config.sourceRules.bankPlayerIds.map(String));
  for (const playerId of selectedPlayerInventoryIds(config.sourceRules)) {
    const label = memberNames.get(playerId) ?? playerId;
    try {
      const envelope = await relayPlayerDataService.inventory({
        configuredClaimId: currentClaimId(),
        claimId: String(claimId),
        playerId,
        forceRefresh,
      });
      catalogWarnings.push(...envelope.warnings.map((warning) => `${label} inventories: ${warning}`));
      const sources = playerInventoryContainerSources(playerId, label, envelope.data, config.sourceRules.deployableContainerIds);
      if (inventoryPlayerIds.has(playerId)) {
        playerSources.push(enrichCraftPlanSourcesFromLocalCatalog(gameCatalogRepository, sources.inventory, catalogWarnings));
      }
      bankSources.push(...enrichCraftPlanSourcesFromLocalCatalog(
        gameCatalogRepository,
        filterSelectedPlayerBankSources(config.sourceRules, sources.banks),
        catalogWarnings,
      ));
      deployableSources.push(...enrichCraftPlanSourcesFromLocalCatalog(gameCatalogRepository, sources.deployables, catalogWarnings));
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      sourceFailures.push({
        sourceId: playerId,
        label: `${label} inventories`,
        type: "Player inventories",
        error: message,
      });
      if (inventoryPlayerIds.has(playerId)) {
        playerSources.push({ sourceId: playerId, label: `${label} inventory`, type: "Player inventory", unavailable: true, error: message, items: [] });
      }
      const exactBankIds = config.sourceRules.bankContainerIds.filter((sourceId) => bankSourceBelongsToPlayer(sourceId, playerId));
      if (bankPlayerIds.has(playerId)) {
        bankSources.push({ sourceId: `${playerId}:banks`, label: `${label} banks`, type: "Player bank", playerId, playerName: label, unavailable: true, error: message, items: [] });
      } else {
        bankSources.push(...exactBankIds.map((sourceId) => ({ sourceId, label: sourceId, type: "Player bank", playerId, playerName: label, unavailable: true, error: message, items: [] })));
      }
      if (config.sourceRules.deployableContainerIds.length) {
        deployableSources.push({ sourceId: `${playerId}:deployables`, label: `${label} deployables`, type: "Player deployable", playerId, playerName: label, unavailable: true, error: message, items: [] });
      }
    }
  }
  const livePlan = computeCraftPlan({
    config,
    detailsByKey,
    catalogWarnings,
    storageSources,
    playerSources,
    bankSources,
    deployableSources,
    activeCrafts: trackedRelayCraftPlanOutputs(
      craftsPayload,
      detailsByKey,
      claimId,
      config.sourceRules.craftPlayerIds,
    ),
    craftSourceErrors: craftsResult.error ? [{
      ...craftsResult.source,
      error: craftsResult.error,
    }] : [],
  });
  const storedEffortModelVersion = Number(statements.getSetting.get("game_catalog_effort_model_version")?.value ?? 0);
  if (storedEffortModelVersion !== CRAFT_PLAN_EFFORT_MODEL_VERSION) {
    livePlan.effortProgress = unavailableCraftPlanEffortProgress();
    return livePlan;
  }
  const catalogRevision = gameCatalogRepository.getEffortWeightRevision(CRAFT_PLAN_EFFORT_MODEL_VERSION);
  const weights = gameCatalogRepository.getEffortWeights(CRAFT_PLAN_EFFORT_MODEL_VERSION);
  const baselineRevision = craftPlanBaselineRevision(config, catalogRevision, CRAFT_PLAN_EFFORT_MODEL_VERSION);
  const baselineConfig = craftPlanBaselineConfig(config);
  const baselineKey = craftPlanEffortBaselineKey(baselineConfig, catalogRevision, CRAFT_PLAN_EFFORT_MODEL_VERSION);
  const baselineStartedAt = Date.now();
  const statsBefore = craftPlanEffortBaselineCache.stats();
  const baselinePlan = await craftPlanEffortBaselineCache.getOrCreate(baselineKey, async () => (
    compactCraftPlanEffortInput(computeCraftPlan({ config: baselineConfig, detailsByKey, catalogWarnings }))
  ));
  const baselineStats = craftPlanEffortBaselineCache.stats();
  if (baselineStats.misses > statsBefore.misses) plannerTelemetry.lastBaselineDurationMs = Date.now() - baselineStartedAt;
  plannerTelemetry.baselineHits = baselineStats.hits;
  plannerTelemetry.baselineMisses = baselineStats.misses;
  plannerTelemetry.baselineInflightReuse = baselineStats.inflightReuse;
  plannerTelemetry.baselineEntries = baselineStats.entries;
  plannerTelemetry.baselineBytes = baselineStats.bytes;
  livePlan.effortProgress = {
    ...calculateCraftPlanEffortProgress({ baselinePlan, currentPlan: livePlan, weights }),
    baselineRevision,
  };

  const sourceStatus = [
    ...storageSources,
    ...playerSources,
    ...bankSources,
    ...deployableSources,
  ].map((source) => ({
    sourceId: String(source?.sourceId ?? ""),
    label: String(source?.label ?? source?.sourceId ?? "Planner source"),
    type: String(source?.type ?? "Planner source"),
    available: source?.unavailable !== true,
    error: source?.unavailable ? String(source?.error ?? "Unavailable") : "",
  }));
  sourceStatus.push(
    { ...inventoriesResult.source, available: !inventoriesResult.error, error: inventoriesResult.error },
    { ...craftsResult.source, available: !craftsResult.error, error: craftsResult.error },
    ...config.sourceRules.craftPlayerIds.flatMap((playerId) => [{
      sourceId: `${String(playerId)}:crafts`,
      label: `${memberNames.get(String(playerId)) ?? playerId} crafts`,
      type: "Tracked crafts",
      available: !craftsResult.error,
      error: craftsResult.error,
    }, {
      sourceId: `${String(playerId)}:passive-crafts`,
      label: `${memberNames.get(String(playerId)) ?? playerId} passive crafts`,
      type: "Tracked passive crafts",
      available: !craftsResult.error,
      error: craftsResult.error,
    }]),
  );

  const capturedAt = new Date().toISOString();
  if (!sourceFailures.length) {
    livePlan.effortProgress.lastSuccessfulAt = capturedAt;
    try {
      const auditResult = craftPlanProgressAudit.recordSuccess(buildCraftPlanProgressSnapshot({
        claimId,
        plan: livePlan,
        sourceStatus,
        weights,
        metadata: {
          capturedAt,
          appVersion,
          buildId: currentAppBuildId(),
          catalogRevision,
          modelVersion: CRAFT_PLAN_EFFORT_MODEL_VERSION,
        },
      }));
      const recentBaselineCutoff = new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString();
      const baselineChange = auditResult.baselineChange ?? craftPlanBaselineChangeSince(claimId, recentBaselineCutoff);
      livePlan.effortProgress.baselineChange = baselineChange?.changedAt > recentBaselineCutoff ? baselineChange : null;
      craftPlanProgressAuditWriteWarning = null;
    } catch (error) {
      craftPlanProgressAuditWriteWarning = {
        at: capturedAt,
        error: (error instanceof Error ? error.message : String(error)).slice(0, 300),
      };
      console.warn(`Craft Plan progress audit write failed: ${craftPlanProgressAuditWriteWarning.error}`);
    }
  } else {
    try {
      craftPlanProgressAudit.recordFailure(claimId, sourceFailures, capturedAt);
      craftPlanProgressAuditWriteWarning = null;
    } catch (error) {
      craftPlanProgressAuditWriteWarning = {
        at: capturedAt,
        error: (error instanceof Error ? error.message : String(error)).slice(0, 300),
      };
      console.warn(`Craft Plan progress audit failure write failed: ${craftPlanProgressAuditWriteWarning.error}`);
    }
    let lastSuccess = null;
    try {
      lastSuccess = craftPlanProgressAudit.latestSuccess(claimId);
    } catch (error) {
      craftPlanProgressAuditWriteWarning = {
        at: capturedAt,
        error: (error instanceof Error ? error.message : String(error)).slice(0, 300),
      };
      console.warn(`Craft Plan progress audit recovery read failed: ${craftPlanProgressAuditWriteWarning.error}`);
    }
    livePlan.effortProgress = lastSuccess?.effortProgress
      ? staleCraftPlanProgress(lastSuccess.effortProgress, sourceFailures, capturedAt)
      : unavailableCraftPlanEffortProgress();
    livePlan.effortProgress.baselineChange = craftPlanBaselineChangeSince(
      claimId,
      new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString(),
    );
    livePlan.unavailableSources = [
      ...(Array.isArray(livePlan.unavailableSources) ? livePlan.unavailableSources : []),
      ...sourceFailures,
    ];
  }
  return livePlan;
}

async function craftPlanDiscordReport(profession = "") {
  try {
    const plan = await computedCraftPlanResponse(getSettings().claimId);
    const cutoff = new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString();
    const reportPlan = craftPlanWithBaselineChange(plan, craftPlanBaselineChangeSince(getSettings().claimId, cutoff));
    return buildCraftPlanDiscordReport(reportPlan, profession);
  } catch (error) {
    return {
      ...buildUnavailableCraftPlanDiscordReport(),
      calculationError: redactServerHealthText(error instanceof Error ? error.message : String(error)).slice(0, 500),
    };
  }
}

async function manualDiscordSandboxMessage(payload, settings, requestedChannelId = "") {
  assertDiscordNetworkEnabled();
  return sendDiscordManualSandboxMessage({
    apiOrigin: discordApiOrigin,
    configuredChannelId: configuredDiscordSandboxChannelId,
    fetchImpl: fetch,
    payload,
    requestedChannelId,
    settings,
  });
}

function discordDeliveryResponse(response) {
  return {
    id: response?.id,
    channel_id: response?.channel_id,
    ...(response?.recorded === true ? { recorded: true } : {}),
  };
}

async function sendCraftPlanDiscordReport({ profession = "", requestedChannelId = "" } = {}) {
  const settings = getDiscordSettingsRaw();
  const metadata = {
    profession: profession || "overview",
    test: true,
    manualSandboxTest: true,
    deliveryMode: configuredDiscordDeliveryMode,
  };
  try {
    const report = await craftPlanDiscordReport(profession);
    const response = await manualDiscordSandboxMessage(
      buildCraftPlanDiscordEmbed(report),
      settings,
      requestedChannelId,
    );
    recordDiscordDeliverySafe({
      status: "sent",
      eventType: "craft_plan_report",
      channelId: configuredDiscordSandboxChannelId,
      channelKey: "manualSandbox",
      summary: report.title,
      metadata: { ...metadata, profession: report.profession || metadata.profession },
      response: discordDeliveryResponse(response),
    });
    return { report, response: discordDeliveryResponse(response) };
  } catch (error) {
    recordDiscordDeliverySafe({
      status: "failed",
      eventType: "craft_plan_report",
      channelId: configuredDiscordSandboxChannelId,
      channelKey: "manualSandbox",
      summary: "Craft Planner report sandbox test",
      error: error instanceof Error ? error.message : String(error),
      metadata,
    });
    throw error;
  }
}

let craftPlanReportDispatcherRunning = false;
let craftPlanReportLastCheckedAt = new Date(Date.now() - 24 * 60 * 60 * 1000);
async function dispatchScheduledCraftPlanReports() {
  if (craftPlanReportDispatcherRunning || !scheduledJobsEnabled || isTestRuntime) return { skipped: true };
  const settings = getDiscordSettingsRaw();
  const reportSettings = settings.craftPlanReports;
  if (!reportSettings.scheduledEnabled) return { skipped: true, reason: "Scheduled Craft Planner reports are disabled" };
  craftPlanReportDispatcherRunning = true;
  let queued = 0;
  try {
    const now = new Date();
    let plan = null;
    let planUnavailable = false;
    for (const rule of reportSettings.rules) {
      const occurrence = dueCraftPlanReportOccurrence(rule, reportSettings.timezone, now, craftPlanReportLastCheckedAt);
      if (!occurrence.due || !validDiscordId(rule.channelId)) continue;
      const claimedAt = now.toISOString();
      const claim = statements.claimDiscordCraftPlanReportOccurrence.run(rule.id, occurrence.key, occurrence.scheduledAt, claimedAt, claimedAt);
      if (!claim.changes) continue;
      try {
        if (!plan && !planUnavailable) {
          try { plan = await computedCraftPlanResponse(getSettings().claimId); }
          catch { planUnavailable = true; }
        }
        const lastSent = statements.latestSentDiscordCraftPlanReportOccurrence.get(rule.id);
        const baselineChange = craftPlanBaselineChangeSince(getSettings().claimId, lastSent?.updated_at ?? "");
        const reportPlan = plan ? craftPlanWithBaselineChange(plan, baselineChange) : null;
        const report = planUnavailable
          ? buildUnavailableCraftPlanDiscordReport()
          : buildCraftPlanDiscordReport(reportPlan, rule.reportType === "profession" ? rule.profession : "");
        await enqueueDiscordActivity("craft_plan_report", report.title, occurrence.scheduledAt, {
          sourceKey: `craft-plan-report:${rule.id}:${occurrence.key}`,
          ruleId: rule.id,
          occurrenceKey: occurrence.key,
          channelId: rule.channelId,
          report,
        }, { sourceKey: `craft-plan-report:${rule.id}:${occurrence.key}` });
        statements.updateDiscordCraftPlanReportOccurrence.run("queued", null, null, new Date().toISOString(), rule.id, occurrence.key);
        queued += 1;
      } catch (error) {
        const message = redactServerHealthText(error instanceof Error ? error.message : String(error)).slice(0, 500);
        statements.deleteDiscordCraftPlanReportOccurrence.run(rule.id, occurrence.key);
        recordDiscordDeliverySafe({ status: "failed", eventType: "craft_plan_report", channelId: rule.channelId, channelKey: "craftPlanReports", summary: "Scheduled Craft Planner report", error: message, metadata: { ruleId: rule.id, occurrenceKey: occurrence.key } });
      }
    }
    craftPlanReportLastCheckedAt = now;
    statements.pruneDiscordCraftPlanReportOccurrences.run(new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString());
    return { checked: reportSettings.rules.length, queued };
  } finally {
    craftPlanReportDispatcherRunning = false;
  }
}
const manualRefreshGuard = createManualRefreshGuard();

function visitorSecuritySettings(includeSecrets = false) {
  return normalizeVisitorSecuritySettings(safeJson(statements.getSetting.get("visitor_security_json")?.value, {}), { includeSecrets });
}

function ipv4ToNumber(ip) {
  const parts = String(ip).split(".").map((part) => Number(part));
  if (parts.length !== 4 || parts.some((part) => !Number.isInteger(part) || part < 0 || part > 255)) return null;
  return (((parts[0] * 256 + parts[1]) * 256 + parts[2]) * 256 + parts[3]) >>> 0;
}

function ipv4CidrMatch(ip, cidr) {
  const [base, bitsText = "32"] = String(cidr).split("/");
  const bits = Number(bitsText);
  const ipNum = ipv4ToNumber(ip);
  const baseNum = ipv4ToNumber(base);
  if (ipNum == null || baseNum == null || !Number.isInteger(bits) || bits < 0 || bits > 32) return false;
  const mask = bits === 0 ? 0 : (0xffffffff << (32 - bits)) >>> 0;
  return (ipNum & mask) === (baseNum & mask);
}

function ipv4CidrRange(cidr) {
  const [base, bitsText = "32"] = String(cidr).split("/");
  const bits = Number(bitsText);
  const baseNum = ipv4ToNumber(base);
  if (baseNum == null || !Number.isInteger(bits) || bits < 0 || bits > 32) return null;
  const mask = bits === 0 ? 0 : (0xffffffff << (32 - bits)) >>> 0;
  const start = (baseNum & mask) >>> 0;
  const size = 2 ** (32 - bits);
  const end = (start + size - 1) >>> 0;
  return { start, end };
}

let geoipCache = { mtimeMs: 0, entries: null, error: null };
const pendingProviderGeoipLookups = new Set();

function isLocalOrPrivateIpAddress(ip) {
  const normalized = normalizeIpAddress(ip);
  if (!normalized) return true;
  if (normalized === "127.0.0.1" || normalized === "0.0.0.0") return true;
  const ipNum = ipv4ToNumber(normalized);
  if (ipNum != null) {
    return ipv4CidrMatch(normalized, "10.0.0.0/8")
      || ipv4CidrMatch(normalized, "172.16.0.0/12")
      || ipv4CidrMatch(normalized, "192.168.0.0/16")
      || ipv4CidrMatch(normalized, "169.254.0.0/16");
  }
  const lower = normalized.toLowerCase();
  return lower === "::1" || lower.startsWith("fc") || lower.startsWith("fd") || lower.startsWith("fe80:");
}

function cacheProviderGeoipResult(ip, provider, country, city, error = null, ttlDays = 30) {
  const nowIso = new Date().toISOString();
  const expiresAt = new Date(Date.now() + Math.max(ttlDays, 1) * 24 * 60 * 60 * 1000).toISOString();
  const key = ipHash(ip);
  statements.upsertVisitorGeoipCache.run(
    key,
    anonymizeIpAddress(ip),
    provider,
    country || "Unknown",
    city || "",
    nowIso,
    expiresAt,
    error,
  );
  if (!error && country && country !== "Unknown") {
    statements.updateVisitorSecurityLocationByIpHash.run(country, city || "", key);
  }
}

async function refreshProviderGeoip(ip, settings) {
  const normalized = normalizeIpAddress(ip);
  const key = ipHash(normalized);
  if (!normalized || isLocalOrPrivateIpAddress(normalized) || pendingProviderGeoipLookups.has(key)) return;
  pendingProviderGeoipLookups.add(key);
  try {
    const response = await fetch(`${ipapiBaseUrl}/${encodeURIComponent(normalized)}/json/`, {
      headers: { "user-agent": appIdentifier },
      signal: AbortSignal.timeout(2500),
    });
    if (!response.ok) throw new Error(`HTTP ${response.status}`);
    const payload = await response.json();
    if (payload?.error) throw new Error(String(payload.reason ?? payload.error));
    const country = String(payload.country_name || payload.country || "Unknown").trim() || "Unknown";
    const city = String(payload.city || "").trim();
    cacheProviderGeoipResult(normalized, "ipapi", country, city, null, settings.geoipCacheDays);
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    cacheProviderGeoipResult(normalized, "ipapi", "Unknown", "", message, 1);
  } finally {
    pendingProviderGeoipLookups.delete(key);
  }
}

function parseGeoipData(text) {
  const trimmed = String(text ?? "").trim();
  if (!trimmed) return [];
  try {
    const parsed = JSON.parse(trimmed);
    const entries = Array.isArray(parsed) ? parsed : Array.isArray(parsed.ranges) ? parsed.ranges : [];
    return entries.map((entry) => ({
      cidr: String(entry.cidr ?? entry.range ?? "").trim(),
      country: String(entry.country ?? entry.countryName ?? "Unknown").trim() || "Unknown",
      city: String(entry.city ?? entry.cityName ?? "").trim(),
    })).filter((entry) => entry.cidr);
  } catch {
    return trimmed.split(/\r?\n/).slice(1).map((line) => {
      const [cidr, country, city] = line.split(",").map((part) => part.trim());
      return { cidr, country: country || "Unknown", city: city || "" };
    }).filter((entry) => entry.cidr);
  }
}

function parseCsvLine(line) {
  const values = [];
  let current = "";
  let quoted = false;
  for (let index = 0; index < String(line).length; index += 1) {
    const char = line[index];
    if (char === '"') {
      if (quoted && line[index + 1] === '"') {
        current += '"';
        index += 1;
      } else {
        quoted = !quoted;
      }
    } else if (char === "," && !quoted) {
      values.push(current);
      current = "";
    } else {
      current += char;
    }
  }
  values.push(current);
  return values;
}

function parseCsvRecords(text) {
  const lines = String(text ?? "").split(/\r?\n/).filter((line) => line.trim());
  if (lines.length < 2) return [];
  const headers = parseCsvLine(lines[0]).map((header) => header.trim());
  return lines.slice(1).map((line) => {
    const values = parseCsvLine(line);
    return Object.fromEntries(headers.map((header, index) => [header, String(values[index] ?? "").trim()]));
  });
}

function readZipEntries(buffer, shouldExtract = () => true) {
  const bytes = Buffer.from(buffer);
  const endSignature = 0x06054b50;
  let endOffset = -1;
  for (let offset = bytes.length - 22; offset >= Math.max(0, bytes.length - 65557); offset -= 1) {
    if (bytes.readUInt32LE(offset) === endSignature) {
      endOffset = offset;
      break;
    }
  }
  if (endOffset < 0) throw new Error("ZIP archive is missing an end-of-central-directory record");
  const totalEntries = bytes.readUInt16LE(endOffset + 10);
  const centralOffset = bytes.readUInt32LE(endOffset + 16);
  const entries = new Map();
  let pointer = centralOffset;
  for (let index = 0; index < totalEntries; index += 1) {
    if (bytes.readUInt32LE(pointer) !== 0x02014b50) throw new Error("ZIP archive has an invalid central directory");
    const compression = bytes.readUInt16LE(pointer + 10);
    const compressedSize = bytes.readUInt32LE(pointer + 20);
    const uncompressedSize = bytes.readUInt32LE(pointer + 24);
    const nameLength = bytes.readUInt16LE(pointer + 28);
    const extraLength = bytes.readUInt16LE(pointer + 30);
    const commentLength = bytes.readUInt16LE(pointer + 32);
    const localOffset = bytes.readUInt32LE(pointer + 42);
    const name = bytes.subarray(pointer + 46, pointer + 46 + nameLength).toString("utf8");
    if (!shouldExtract(name)) {
      pointer += 46 + nameLength + extraLength + commentLength;
      continue;
    }
    if (bytes.readUInt32LE(localOffset) !== 0x04034b50) throw new Error(`ZIP archive has an invalid local header for ${name}`);
    const localNameLength = bytes.readUInt16LE(localOffset + 26);
    const localExtraLength = bytes.readUInt16LE(localOffset + 28);
    const dataStart = localOffset + 30 + localNameLength + localExtraLength;
    const compressed = bytes.subarray(dataStart, dataStart + compressedSize);
    let data;
    if (compression === 0) data = compressed;
    else if (compression === 8) data = inflateRawSync(compressed);
    else throw new Error(`ZIP entry ${name} uses unsupported compression method ${compression}`);
    if (uncompressedSize && data.length !== uncompressedSize) throw new Error(`ZIP entry ${name} has an unexpected size`);
    entries.set(name, data.toString("utf8"));
    pointer += 46 + nameLength + extraLength + commentLength;
  }
  return entries;
}

function parseMaxMindCityCsvZip(buffer) {
  const entries = readZipEntries(buffer, (name) => /GeoLite2-City-(Locations-en|Blocks-IPv4)\.csv$/i.test(name));
  const locationsEntry = [...entries.entries()].find(([name]) => /GeoLite2-City-Locations-en\.csv$/i.test(name));
  const blocksEntry = [...entries.entries()].find(([name]) => /GeoLite2-City-Blocks-IPv4\.csv$/i.test(name));
  if (!locationsEntry || !blocksEntry) throw new Error("GeoIP ZIP must contain GeoLite2-City-Locations-en.csv and GeoLite2-City-Blocks-IPv4.csv");
  const locations = new Map(parseCsvRecords(locationsEntry[1]).map((row) => [
    String(row.geoname_id ?? ""),
    {
      country: String(row.country_name || row.country_iso_code || "Unknown").trim() || "Unknown",
      city: String(row.city_name || "").trim(),
    },
  ]));
  return parseCsvRecords(blocksEntry[1]).map((row) => {
    const location = locations.get(String(row.geoname_id ?? "")) || locations.get(String(row.registered_country_geoname_id ?? "")) || {};
    return {
      cidr: String(row.network ?? "").trim(),
      country: String(location.country ?? "Unknown").trim() || "Unknown",
      city: String(location.city ?? "").trim(),
    };
  }).filter((entry) => entry.cidr);
}

function* csvLineIterator(text) {
  const source = String(text ?? "");
  let start = 0;
  for (let index = 0; index <= source.length; index += 1) {
    const char = source[index];
    if (index === source.length || char === "\n") {
      const line = source.slice(start, index).replace(/\r$/, "");
      start = index + 1;
      if (line.trim()) yield line;
    }
  }
}

function* csvRecordIterator(text) {
  const iterator = csvLineIterator(text);
  const first = iterator.next();
  if (first.done) return;
  const headers = parseCsvLine(first.value).map((header) => header.trim());
  for (const line of iterator) {
    const values = parseCsvLine(line);
    yield Object.fromEntries(headers.map((header, index) => [header, String(values[index] ?? "").trim()]));
  }
}

async function importMaxMindCityCsvZipToSqlite(buffer, progress = () => {}) {
  const zipEntries = readZipEntries(buffer, (name) => /GeoLite2-City-(Locations-en|Blocks-IPv4)\.csv$/i.test(name));
  const locationsEntry = [...zipEntries.entries()].find(([name]) => /GeoLite2-City-Locations-en\.csv$/i.test(name));
  const blocksEntry = [...zipEntries.entries()].find(([name]) => /GeoLite2-City-Blocks-IPv4\.csv$/i.test(name));
  if (!locationsEntry || !blocksEntry) throw new Error("GeoIP ZIP must contain GeoLite2-City-Locations-en.csv and GeoLite2-City-Blocks-IPv4.csv");
  progress({ stage: "indexing_locations" });
  const locations = new Map();
  let locationRows = 0;
  for (const row of csvRecordIterator(locationsEntry[1])) {
    const key = String(row.geoname_id ?? "");
    if (key) {
      locations.set(key, {
        country: String(row.country_name || row.country_iso_code || "Unknown").trim() || "Unknown",
        city: String(row.city_name || "").trim(),
      });
    }
    locationRows += 1;
    if (locationRows % 5000 === 0) {
      progress({ stage: "indexing_locations", locationRows });
      await delay(0);
    }
  }

  progress({ stage: "writing_ranges", locationRows, rangeRows: 0 });
  const updatedAt = new Date().toISOString();
  db.exec(`
    DROP TABLE IF EXISTS geoip_ranges_import;
    CREATE TABLE geoip_ranges_import (
      ip_start INTEGER NOT NULL,
      ip_end INTEGER NOT NULL,
      country TEXT NOT NULL,
      city TEXT,
      updated_at TEXT NOT NULL,
      PRIMARY KEY (ip_start, ip_end)
    );
  `);
  const insertImportRange = db.prepare("INSERT OR IGNORE INTO geoip_ranges_import (ip_start, ip_end, country, city, updated_at) VALUES (?, ?, ?, ?, ?)");
  try {
    let count = 0;
    db.exec("BEGIN");
    for (const row of csvRecordIterator(blocksEntry[1])) {
      const cidr = String(row.network ?? "").trim();
      if (!cidr) continue;
      const range = ipv4CidrRange(cidr);
      if (!range) continue;
      const location = locations.get(String(row.geoname_id ?? "")) || locations.get(String(row.registered_country_geoname_id ?? "")) || {};
      insertImportRange.run(range.start, range.end, String(location.country ?? "Unknown").trim() || "Unknown", String(location.city ?? "").trim(), updatedAt);
      count += 1;
      if (count % 25000 === 0) {
        db.exec("COMMIT");
        progress({ stage: "writing_ranges", locationRows, rangeRows: count });
        db.exec("BEGIN");
        await delay(0);
      }
    }
    db.exec("COMMIT");
    db.exec(`
      DELETE FROM geoip_ranges;
      INSERT INTO geoip_ranges (ip_start, ip_end, country, city, updated_at)
      SELECT ip_start, ip_end, country, city, updated_at FROM geoip_ranges_import;
      DROP TABLE geoip_ranges_import;
    `);
    return { entries: count, locationRows };
  } catch (error) {
    try {
      db.exec("ROLLBACK");
    } catch {}
    try {
      db.exec("DROP TABLE IF EXISTS geoip_ranges_import");
    } catch {}
    throw error;
  }
}

function parseGeoipDownload(body, contentType = "") {
  const buffer = Buffer.from(body);
  const looksZip = buffer.length >= 4 && buffer.readUInt32LE(0) === 0x04034b50;
  if (looksZip || /zip/i.test(contentType)) return parseMaxMindCityCsvZip(buffer);
  return parseGeoipData(buffer.toString("utf8"));
}

function geoipFileEntryCount() {
  if (!existsSync(geoipDataPath)) return 0;
  const stat = statSync(geoipDataPath);
  if (stat.size > maxGeoipJsonFallbackBytes) {
    geoipCache = {
      mtimeMs: stat.mtimeMs,
      entries: [],
      error: `GeoIP JSON fallback is too large to load safely (${Math.round(stat.size / 1024 / 1024)} MB). Run the GeoIP refresh again to import it into SQLite.`,
    };
    return 0;
  }
  const tailLength = Math.min(stat.size, 4096);
  if (!tailLength) return 0;
  const fd = openSync(geoipDataPath, "r");
  try {
    const buffer = Buffer.alloc(tailLength);
    readSync(fd, buffer, 0, tailLength, stat.size - tailLength);
    const tail = buffer.toString("utf8");
    const match = tail.match(/"count"\s*:\s*(\d+)/);
    if (match) return Number(match[1]);
  } finally {
    closeSync(fd);
  }
  return loadGeoipEntries().length;
}

function geoipStatus() {
  const settings = visitorSecuritySettings();
  if (settings.geoipProvider === "ipapi") {
    return {
      configured: true,
      provider: "ipapi",
      storage: "provider-cache",
      path: null,
      entries: toNumber(statements.visitorGeoipCacheCount.get()?.count),
      lastUpdatedAt: statements.visitorGeoipCacheLastLookup.get()?.looked_up_at ?? null,
      error: null,
    };
  }
  if (settings.geoipProvider === "disabled") {
    return { configured: false, provider: "disabled", storage: "disabled", path: null, entries: 0, lastUpdatedAt: null, error: null };
  }
  const sqliteEntries = toNumber(statements.geoipRangeCount.get()?.count);
  if (sqliteEntries > 0) {
    return {
      configured: true,
      provider: "local",
      storage: "sqlite",
      path: databasePath,
      entries: sqliteEntries,
      lastUpdatedAt: statements.geoipRangeLastUpdated.get()?.updated_at ?? null,
      error: geoipCache.error,
    };
  }
  if (!existsSync(geoipDataPath)) {
    return { configured: false, provider: "local", storage: "none", path: geoipDataPath, entries: 0, lastUpdatedAt: null, error: null };
  }
  try {
    const stat = statSync(geoipDataPath);
    if (stat.size > maxGeoipJsonFallbackBytes) {
      return {
        configured: false,
        storage: "json-skipped",
        path: geoipDataPath,
        entries: 0,
        lastUpdatedAt: new Date(stat.mtimeMs).toISOString(),
        error: `GeoIP JSON fallback is too large to load safely (${Math.round(stat.size / 1024 / 1024)} MB). Run the GeoIP refresh again to import it into SQLite.`,
      };
    }
    return { configured: true, provider: "local", storage: "json", path: geoipDataPath, entries: geoipFileEntryCount(), lastUpdatedAt: new Date(stat.mtimeMs).toISOString(), error: geoipCache.error };
  } catch (error) {
    return { configured: false, provider: "local", storage: "none", path: geoipDataPath, entries: 0, lastUpdatedAt: null, error: error instanceof Error ? error.message : String(error) };
  }
}

function loadGeoipEntries() {
  if (!existsSync(geoipDataPath)) return [];
  const stat = statSync(geoipDataPath);
  if (stat.size > maxGeoipJsonFallbackBytes) {
    geoipCache = {
      mtimeMs: stat.mtimeMs,
      entries: [],
      error: `GeoIP JSON fallback is too large to load safely (${Math.round(stat.size / 1024 / 1024)} MB). Run the GeoIP refresh again to import it into SQLite.`,
    };
    return [];
  }
  if (geoipCache.entries && geoipCache.mtimeMs === stat.mtimeMs) return geoipCache.entries;
  try {
    const entries = parseGeoipData(readFileSync(geoipDataPath, "utf8"));
    geoipCache = { mtimeMs: stat.mtimeMs, entries, error: null };
    return entries;
  } catch (error) {
    geoipCache = { mtimeMs: stat.mtimeMs, entries: [], error: error instanceof Error ? error.message : String(error) };
    return [];
  }
}

function lookupGeoip(ipAddress) {
  const ip = normalizeIpAddress(ipAddress);
  const settings = visitorSecuritySettings();
  if (settings.geoipProvider === "disabled") return { country: "Unknown", city: "" };
  if (settings.geoipProvider === "ipapi") {
    if (isLocalOrPrivateIpAddress(ip)) return { country: "Unknown", city: "" };
    const cached = statements.getVisitorGeoipCache.get(ipHash(ip));
    if (cached && new Date(cached.expires_at).getTime() > Date.now()) {
      return { country: cached.country || "Unknown", city: cached.city || "" };
    }
    void refreshProviderGeoip(ip, settings).catch(() => {});
    return { country: "Unknown", city: "" };
  }
  const ipNum = ipv4ToNumber(ip);
  if (ipNum != null) {
    const row = statements.lookupGeoipRange.get(ipNum, ipNum);
    if (row) return { country: row.country || "Unknown", city: row.city || "" };
  }
  for (const entry of loadGeoipEntries()) {
    if (ipv4CidrMatch(ip, entry.cidr)) return { country: entry.country || "Unknown", city: entry.city || "" };
  }
  return { country: "Unknown", city: "" };
}

let lastVisitorSecurityPruneAt = 0;

function pruneVisitorSecurityEvents() {
  const settings = visitorSecuritySettings();
  const nowMs = Date.now();
  const fullIpBefore = new Date(nowMs - settings.fullIpRetentionDays * 24 * 60 * 60 * 1000).toISOString();
  const statsBefore = new Date(nowMs - settings.statsRetentionDays * 24 * 60 * 60 * 1000).toISOString();
  db.prepare("UPDATE visitor_security_events SET ip_address = NULL WHERE occurred_at < ? AND ip_address IS NOT NULL").run(fullIpBefore);
  db.prepare("DELETE FROM visitor_security_events WHERE occurred_at < ?").run(statsBefore);
  statements.pruneVisitorGeoipCache.run(new Date(nowMs).toISOString());
  lastVisitorSecurityPruneAt = nowMs;
}

function recordVisitorSecurityEvent(req, pathname, statusCode) {
  // Visitor security logging is treated as legitimate-interest server telemetry:
  // it stores short-lived IP data for abuse investigation, then relies on hashed
  // and approximate geo fields for longer-term statistics.
  if (!shouldLogVisitor(pathname)) return;
  const nowIso = new Date().toISOString();
  if (Date.now() - lastVisitorSecurityPruneAt > 60 * 60 * 1000) pruneVisitorSecurityEvents();
  const ip = normalizeIpAddress(requestAddress(req));
  const anonymized = anonymizeIpAddress(ip);
  const userAgent = String(req.headers["user-agent"] ?? "").slice(0, 500);
  const userAgentHash = userAgent ? createHash("sha256").update(userAgent).digest("hex") : null;
  const visitorKey = createHash("sha256").update(`${anonymized}|${userAgentHash ?? ""}`).digest("hex");
  const location = lookupGeoip(ip);
  statements.insertVisitorSecurityEvent.run(
    nowIso,
    String(req.method ?? "GET"),
    routeGroup(pathname),
    toNumber(statusCode) || 0,
    `${Math.floor((toNumber(statusCode) || 0) / 100)}xx`,
    ip || null,
    anonymized,
    ipHash(ip),
    visitorKey,
    userAgentHash,
    location.country,
    location.city,
  );
}

function visitorSecurityDashboard(params = new URLSearchParams()) {
  const query = params instanceof URLSearchParams ? params : new URLSearchParams(`days=${encodeURIComponent(String(params ?? 30))}`);
  const selectedDays = [1, 7, 30, 90].includes(Number(query.get("days"))) ? Number(query.get("days")) : 30;
  const eventPageSize = Math.min(Math.max(Math.floor(toNumber(query.get("eventPageSize")) || 50), 10), 250);
  const eventPage = Math.max(Math.floor(toNumber(query.get("eventPage")) || 1), 1);
  const eventSearch = String(query.get("eventSearch") ?? "").trim().slice(0, 120);
  const eventStatus = String(query.get("eventStatus") ?? "").trim().slice(0, 3);
  const eventGroup = String(query.get("eventGroup") ?? "").trim().slice(0, 80);
  const since = new Date(Date.now() - selectedDays * 24 * 60 * 60 * 1000).toISOString();
  const totals = db.prepare(`
    SELECT COUNT(*) AS requests,
      COUNT(DISTINCT visitor_key) AS uniqueVisitors,
      COUNT(CASE WHEN status_code >= 400 THEN 1 END) AS errors
    FROM visitor_security_events WHERE occurred_at >= ?
  `).get(since);
  const locations = db.prepare(`
    SELECT COALESCE(country, 'Unknown') AS country, COALESCE(city, '') AS city,
      COUNT(*) AS requests, COUNT(DISTINCT visitor_key) AS visitors
    FROM visitor_security_events
    WHERE occurred_at >= ?
    GROUP BY COALESCE(country, 'Unknown'), COALESCE(city, '')
    ORDER BY requests DESC, visitors DESC
    LIMIT 30
  `).all(since);
  const routes = db.prepare(`
    SELECT route_group AS routeGroup, COUNT(*) AS requests, COUNT(CASE WHEN status_code >= 400 THEN 1 END) AS errors
    FROM visitor_security_events
    WHERE occurred_at >= ?
    GROUP BY route_group
    ORDER BY requests DESC
    LIMIT 20
  `).all(since);
  const recentWhere = ["occurred_at >= ?"];
  const recentArgs = [since];
  if (eventSearch) {
    const pattern = `%${escapeSqlLike(eventSearch)}%`;
    recentWhere.push(`(
      method LIKE ? ESCAPE '\\'
      OR route_group LIKE ? ESCAPE '\\'
      OR CAST(status_code AS TEXT) LIKE ? ESCAPE '\\'
      OR ip_address LIKE ? ESCAPE '\\'
      OR ip_anonymized LIKE ? ESCAPE '\\'
      OR country LIKE ? ESCAPE '\\'
      OR city LIKE ? ESCAPE '\\'
    )`);
    recentArgs.push(pattern, pattern, pattern, pattern, pattern, pattern, pattern);
  }
  if (eventStatus) {
    recentWhere.push("CAST(status_code AS TEXT) LIKE ? ESCAPE '\\'");
    recentArgs.push(`${escapeSqlLike(eventStatus)}%`);
  }
  if (eventGroup) {
    recentWhere.push("route_group = ?");
    recentArgs.push(eventGroup);
  }
  const recentWhereSql = recentWhere.join(" AND ");
  const recentTotal = toNumber(db.prepare(`SELECT COUNT(*) AS count FROM visitor_security_events WHERE ${recentWhereSql}`).get(...recentArgs)?.count);
  const recentOffset = Math.min((eventPage - 1) * eventPageSize, Math.max(recentTotal - 1, 0));
  const recentRows = db.prepare(`
    SELECT id, occurred_at AS occurredAt, method, route_group AS routeGroup, status_code AS statusCode,
      ip_address AS ipAddress, ip_anonymized AS ipAnonymized, country, city
    FROM visitor_security_events
    WHERE ${recentWhereSql}
    ORDER BY occurred_at DESC, id DESC
    LIMIT ? OFFSET ?
  `).all(...recentArgs, eventPageSize, recentOffset);
  const retentionSettings = visitorSecuritySettings();
  return {
    days: selectedDays,
    retention: { ...retentionSettings, fullIpDays: retentionSettings.fullIpRetentionDays },
    geoip: geoipStatus(),
    totals,
    locations,
    routes,
    recent: {
      rows: recentRows,
      total: recentTotal,
      page: Math.floor(recentOffset / eventPageSize) + 1,
      pageSize: eventPageSize,
      search: eventSearch,
      status: eventStatus,
      group: eventGroup,
    },
  };
}



